"""Plan, apply, check and diff generated files with clobber protection.

Ownership rules (what `sync` may overwrite without --force):
  * the file / managed part doesn't exist yet, or already matches;
  * its hash matches what we last wrote (recorded in .agents/samerules.lock);
  * it carries our "Generated by samerules" marker and the lock has no entry.
Everything else (hand-written files, generated files edited by hand) is a
conflict that needs --force.
"""

import difflib
import hashlib
import json
import os
from dataclasses import dataclass
from typing import Optional

from . import targets as targets_mod
from .handlers import MergeError
from .source import LOCK_FILE, SOURCE_DIR

OK, CREATE, UPDATE, DELETE, CONFLICT = "ok", "create", "update", "delete", "conflict"


def sha(part):
    if part is None:
        return None
    if isinstance(part, str):
        part = part.encode("utf-8")
    return hashlib.sha256(part).hexdigest()


def lock_path(root):
    return os.path.join(root, SOURCE_DIR, LOCK_FILE)


def read_lock(root):
    p = lock_path(root)
    if not os.path.isfile(p):
        return {}
    try:
        with open(p, encoding="utf-8") as fh:
            data = json.load(fh)
        files = data.get("files", {})
        return {k: v for k, v in files.items() if isinstance(v, str)}
    except (ValueError, AttributeError, OSError):
        return {}


def write_lock(root, files):
    data = {"generator": "samerules", "note": "hashes of generated files; commit this file",
            "version": 1, "files": dict(sorted(files.items()))}
    text = json.dumps(data, indent=2) + "\n"
    p = lock_path(root)
    old = None
    if os.path.isfile(p):
        with open(p, encoding="utf-8") as fh:
            old = fh.read()
    if old != text:
        with open(p, "w", encoding="utf-8") as fh:
            fh.write(text)
        return True
    return False


@dataclass
class Item:
    path: str
    action: str
    reason: str
    handler: object
    current: Optional[bytes]
    want: object  # desired managed part, None = remove
    new_bytes: Optional[bytes] = None  # full file after applying
    mode: int = 0o644
    targets: tuple = ()


def _safe(root, rel):
    full = os.path.normpath(os.path.join(root, rel))
    if os.path.commonpath([full, os.path.abspath(root)]) != os.path.abspath(root):
        raise ValueError("refusing to touch %s: outside the project" % rel)
    return full


def _read_bytes(path):
    if not os.path.isfile(path):
        return None
    with open(path, "rb") as fh:
        return fh.read()


def plan(src, force=False):
    outputs, warnings = targets_mod.render(src)
    lock = read_lock(src.root)
    items = []
    wanted = {o.path for o in outputs}
    todo = [(o.path, o.handler, o.part, o.mode, tuple(o.targets)) for o in outputs]
    for path in sorted(lock):
        if path not in wanted:
            todo.append((path, targets_mod.handler_for(path), None, 0o644, ()))
    for path, handler, want, mode, tgts in todo:
        if hasattr(handler, "force"):
            handler.force = force
        full = _safe(src.root, path)
        if os.path.isdir(full) and not os.path.islink(full):
            items.append(Item(path, CONFLICT, "is a directory", handler, None, want, targets=tgts))
            continue
        if os.path.islink(full):
            items.append(Item(path, CONFLICT, "is a symlink; samerules won't write through it",
                              handler, None, want, targets=tgts))
            continue
        current = _read_bytes(full)
        try:
            cur_part = handler.extract(current) if current is not None else None
        except MergeError as e:
            items.append(Item(path, CONFLICT, str(e), handler, current, want, targets=tgts))
            continue
        it = Item(path, OK, "", handler, current, want, mode=mode, targets=tgts)
        locked = lock.get(path)
        if cur_part == want:
            it.action, it.reason = OK, "up to date"
        elif cur_part is None:
            it.action = CREATE
            it.reason = "missing" if current is None else "add managed section"
        else:
            ours_unchanged = locked is not None and locked == sha(cur_part)
            marked_unknown = locked is None and handler.has_marker(cur_part)
            if want is None:
                it.action = DELETE
                it.reason = "no longer generated"
            else:
                it.action = UPDATE
                it.reason = "out of date: .agents/ changed since last sync"
            if not (ours_unchanged or marked_unknown):
                if locked is not None:
                    why = "edited by hand since the last sync (move the change into .agents/)"
                elif handler.kind == "file":
                    why = "hand-written file, not generated by samerules"
                else:
                    why = "existing settings differ and weren't written by samerules"
                if force:
                    it.reason = why + "; overwriting (--force)"
                else:
                    it.action, it.reason = CONFLICT, why + "; use --force to overwrite"
        if it.action in (CREATE, UPDATE, DELETE):
            try:
                it.new_bytes = handler.render(current, want)
            except MergeError as e:
                it.action, it.reason = CONFLICT, str(e)
        items.append(it)
    order = {CONFLICT: 0, CREATE: 1, UPDATE: 2, DELETE: 3, OK: 4}
    items.sort(key=lambda i: (order[i.action], i.path))
    return items, warnings


def _prune_dirs(root, rel):
    d = os.path.dirname(os.path.join(root, rel))
    root = os.path.abspath(root)
    while os.path.abspath(d) != root and os.path.isdir(d) and not os.listdir(d):
        os.rmdir(d)
        d = os.path.dirname(d)


def apply(src, items):
    """Write every non-conflict change. Returns counts."""
    lock = read_lock(src.root)
    counts = {CREATE: 0, UPDATE: 0, DELETE: 0, CONFLICT: 0, OK: 0}
    for it in items:
        counts[it.action] += 1
        full = _safe(src.root, it.path)
        if it.action == CONFLICT:
            continue
        if it.action == OK:
            if it.want is not None:
                lock[it.path] = sha(it.want)
            else:
                lock.pop(it.path, None)
            continue
        if it.new_bytes is None:
            if os.path.isfile(full):
                os.remove(full)
                _prune_dirs(src.root, it.path)
        else:
            os.makedirs(os.path.dirname(full) or ".", exist_ok=True)
            tmp = full + ".samerules-tmp"
            with open(tmp, "wb") as fh:
                fh.write(it.new_bytes)
            os.replace(tmp, full)
            if it.handler.kind == "file":
                try:
                    os.chmod(full, it.mode)
                except OSError:
                    pass
        if it.want is None:
            lock.pop(it.path, None)
        else:
            lock[it.path] = sha(it.want)
    write_lock(src.root, lock)
    return counts


def _text(b):
    if b is None:
        return None
    try:
        return b.decode("utf-8")
    except UnicodeDecodeError:
        return None


def unified(it):
    """Unified diff from the current file to what sync would write."""
    if it.action == OK:
        return ""
    after = it.new_bytes
    if it.action == CONFLICT and after is None and it.want is not None:
        try:
            after = it.handler.render(it.current, it.want)
        except MergeError:
            return ""
    a, b = _text(it.current or b""), _text(after or b"")
    if a is None or b is None:
        return "Binary file %s differs\n" % it.path
    lines = difflib.unified_diff(
        a.splitlines(True), b.splitlines(True),
        fromfile="a/" + it.path if it.current is not None else "/dev/null",
        tofile="b/" + it.path if after is not None else "/dev/null")
    out = []
    for ln in lines:
        out.append(ln if ln.endswith("\n") else ln + "\n\\ No newline at end of file\n")
    return "".join(out)
